// Set the message displayed on the note using the raw function to preserve all Newlines and BlankSpaces

const bodyPayload = String.raw`-------------------- AUTOMATED NOTE ------------------- \n\n \u200B \n\n No participant was found in this ticket, this must be someone else in behalf of the participant, or any partner's email such as RightSignature, LT Trust, etc.\n\n \u200B \n\n Please review and proceed accordingly.`;

var tag = String.raw`{"id": "don:core:dvrv-us-1:devo/1is7v8y722:tag/2909"}`;

if ( $input.first().json.first_contact === 'false') {

  tag += String.raw`,
  {"id": "don:core:dvrv-us-1:devo/1is7v8y722:tag/2887"}`

}else{

  tag += String.raw`,
  {"id": "don:core:dvrv-us-1:devo/1is7v8y722:tag/2886"}`

}

// Return payload

return{

  json:{

    "ticketId":$('Get fields1').first().json.ticketId,
    "body": bodyPayload,
    "part": "CAPL-1",
    "tag": tag
  }
};

// Normalize the authenticated DevRev work response and capture ticket authority.
const works = $input.first().json.work;

if (!works || typeof works !== 'object') {
  throw new Error('Missing DevRev work response');
}

const displayCandidate =
  typeof works.display_id === 'string' ? works.display_id.trim() : '';
const donCandidate = typeof works.id === 'string' ? works.id.trim() : '';
const displayId = /^[A-Za-z][A-Za-z0-9]{0,15}-[0-9]{1,20}$/;
const devrevDon = /^don:[A-Za-z0-9_.:/+-]{1,252}$/;

const ticketId = displayId.test(displayCandidate)
  ? displayCandidate.toUpperCase()
  : (devrevDon.test(donCandidate) ? donCandidate : '');

if (!ticketId) {
  throw new Error('Missing or invalid DevRev response ticket identity');
}

const lookupTicketId = $('Validate Ticket Lookup').first().json.ticketId;
const normalizedDisplay = displayId.test(displayCandidate)
  ? displayCandidate.toUpperCase()
  : displayCandidate;
if (lookupTicketId !== normalizedDisplay && lookupTicketId !== donCandidate) {
  throw new Error('DevRev response ticket identity mismatch');
}

const reporter = (works.reported_by && works.reported_by[0]) || {};

return {
  json: {
    userId: reporter.id || null,
    userName: reporter.display_name || null,
    userEmail: reporter.email || null,
    ticketId,
    ticketDisplayId: displayCandidate || null,
    emailSubject: works.title || null,
    emailBody: works.body || null,
    tags: Array.isArray(works.tags)
      ? works.tags.map(tagObj => tagObj.tag.name)
      : [],
  },
};

// Obtener array de etiquetas
const tagsArray = $json.tags;

// Definir etiquetas a excluir
const excludedTags = [
  "First Contact", "help@forusall.com", "Automated Email", "Followup Reopened",
  "Issue", "LT Salesforce Ticket", "Force Out Notice", "IRS Notice",
  "Orphan", "noreply@forusall.com"
];

// Filtrar todas las etiquetas excepto las excluidas
const filteredTags = tagsArray.filter(tag => !excludedTags.includes(tag));

// Obtener un solo tag (el primero filtrado) o "NOT FOUND"
const tag = filteredTags.length > 0 ? filteredTags[0] : "NOT FOUND";

// Marcar true si "First Contact" está presente
const firstContact = tagsArray.includes("First Contact");

// Salida
return {
  json: {
    userId: $json.userId,
    userName: $json.userName,
    userEmail: $json.userEmail,
    ticketId: $json.ticketId,
    emailSubject: $json.emailSubject,
    emailBody: $json.emailBody,
    tag,
    firstContact
  }
};

const rawTicketId = $json?.body?.id;

if (typeof rawTicketId !== 'string') {
  throw new Error('Missing canonical DevRev ticket identity');
}

const candidate = rawTicketId.trim();
const displayId = /^[A-Za-z][A-Za-z0-9]{0,15}-[0-9]{1,20}$/;
const devrevDon = /^don:[A-Za-z0-9_.:/+-]{1,252}$/;

if (!displayId.test(candidate) && !devrevDon.test(candidate)) {
  throw new Error('Invalid canonical DevRev ticket identity');
}

const ticketId = displayId.test(candidate) ? candidate.toUpperCase() : candidate;

return {
  json: {
    ...$json,
    ticketId,
  },
};

// Búsqueda en anchura (BFS) que respeta el orden de inserción y de los arrays
function findAllKeysOrdered(obj, targetKey) {
  const out = [];
  const queue = [obj];

  while (queue.length) {
    const current = queue.shift();
    if (current && typeof current === 'object') {
      // 1) Capturamos primero todas las coincidencias en el nivel actual, en orden
      for (const [k, v] of Object.entries(current)) {
        if (k === targetKey) out.push(v);
      }
      // 2) Encolamos después los hijos, en el mismo orden
      for (const v of Object.values(current)) {
        if (v && typeof v === 'object') queue.push(v);
      }
    }
  }
  return out;
}

function coerceToObject(maybeJsonLike) {
  if (maybeJsonLike && typeof maybeJsonLike === 'object') return maybeJsonLike;
  if (typeof maybeJsonLike === 'string') {
    const trimmed = maybeJsonLike.trim();
    if ((trimmed.startsWith('{') && trimmed.endsWith('}')) ||
        (trimmed.startsWith('[') && trimmed.endsWith(']'))) {
      try { return JSON.parse(trimmed); } catch (_) {}
    }
  }
  return undefined;
}

function toSafeString(v) {
  if (v == null) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') {
    try { return JSON.stringify(v); } catch (_) { return String(v); }
  }
  return String(v);
}

// 1) Acumular TODOS los `body` de TODOS los items en ORDEN
const collected = [];
for (const item of items) {
  const candidate =
    item.json?.payload ??
    item.json?.data ??
    item.json?.body ??
    item.json;

  const root = coerceToObject(candidate) ?? item.json;
  const found = findAllKeysOrdered(root, 'body'); // target: "body"
  if (found.length) collected.push(...found);
}

// 2) Tomamos el item base del nodo previo
const base = $('Get relevant tag1').first();
const baseJson = base?.json ?? {};

// 3) Construimos ticket_messages en orden: message_1, message_2, ...
const ticket_messages = {};
for (let i = 0; i < collected.length; i++) {
  ticket_messages[`message_${i + 1}`] = toSafeString(collected[i]);
}

// 4) Retornamos un solo item con ticket_messages
return [{
  json: {
    ...baseJson,
    ticket_messages
  }
}];

var data = $('Obtain the real message from the PPT').first().json;

data.firstContact = $input.first().json.output.firstContact;

if (data.ticket_messages && typeof data.ticket_messages === 'object') {
  for (const key in data.ticket_messages) {
    if (typeof data.ticket_messages[key] === 'string') {
      data.ticket_messages[key] = data.ticket_messages[key]
        .replace(/\\n/g, ' ')      // removes literal "\n"
        .replace(/\r?\n/g, ' ')    // removes real line breaks
        .replace(/\s+/g, ' ')      // normalizes extra spaces
        .trim();
    }
  }
}

return {
  json: {
    ...data
  }
};

function fnv1a64(value) {
  let hash = 0xcbf29ce484222325n;
  const prime = 0x100000001b3n;

  for (let index = 0; index < value.length; index += 1) {
    const codeUnit = value.charCodeAt(index);
    hash ^= BigInt(codeUnit & 0xff);
    hash = BigInt.asUintN(64, hash * prime);
    hash ^= BigInt(codeUnit >>> 8);
    hash = BigInt.asUintN(64, hash * prime);
  }

  return hash.toString(16).padStart(16, '0');
}

const userData = $input.first().json.userData;
const forusbots = $input.first().json.fubData;
const ticketData = $('Code').first().json;
const ticketId = $('Get fields1').first().json.ticketId;
const canonicalTicketData = {
  ...ticketData,
  ticketId,
};

const envelope = {
  participant_id: userData.pptId ?? '',
  plan_id: userData.planId ?? '',
  company_name: userData.companyName ?? '',
  company_status: userData.companyStatus ?? '',
  company_status_detail: userData.companyStatusDetail ?? '',
  record_keeper: forusbots.recordKeeper ?? '',
  ticket_handler_mode: 'full',
  max_response_tokens: 5500,
  ticket: {
    username: canonicalTicketData.userName ?? '',
    user_email: canonicalTicketData.userEmail ?? '',
    email_subject: canonicalTicketData.emailSubject ?? '',
    email_body: canonicalTicketData.emailBody ?? '',
    ticket_messages: canonicalTicketData.ticket_messages ?? {},
    tag: null,
    ticket_id: ticketId,
    first_contact: null,
  },
};
const idempotencyKey =
  'n8n-handle-v1-' + fnv1a64(JSON.stringify(envelope));

return {
  userData,
  ticketData: canonicalTicketData,
  forusbots,
  idempotencyKey,
};

function escapeJSONStringForHTTP(obj) {
  const compact = JSON.stringify(obj);
  const escaped = compact
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"');
  return escaped;
}

// ---- inputs ------------------------------------------------------------
const raw = $input.first().json;
// /handle-ticket devuelve un array (o un objeto en la ruta inline). Normalizamos.
const data = Array.isArray(raw) ? raw[0] : raw;

const getFields = $('Get fields1').first().json;
const firstContact =
  getFields.caseData?.ticketData?.firstContact ??
  getFields.ticketData?.firstContact ??
  getFields.firstContact;

// ---- quedarse SOLO con lo que el LLM redactor necesita ------------------
function cleanInquiry(iq) {
  if (!iq) return null;

  const out = {
    inquiry: iq.inquiry,
    topic: iq.topic,
    route: iq.route,
  };

  // Ruta generate_response: contenido accionable para el participante
  const r = iq.generate_response?.response;
  if (r) {
    out.outcome = r.outcome;
    out.response_to_participant = r.response_to_participant; // opening, key_points, steps, warnings
    out.questions_to_ask = r.questions_to_ask;
    out.escalation = r.escalation;
  }

  // Ruta knowledge_question
  if (iq.knowledge_answer) {
    out.knowledge_answer = {
      answer: iq.knowledge_answer.answer,
      key_points: iq.knowledge_answer.key_points,
    };
  }

  // Ruta needs_more_info
  if (iq.needs_more_info_message) {
    out.needs_more_info_message = iq.needs_more_info_message;
  }

  return out;
}

// primary + related (soporta tickets multi-inquiry, p.ej. financiero + account_access)
const inquiries = [data.primary, ...(data.related || [])]
  .filter(Boolean)
  .map(cleanInquiry);

const payload = {
  responseSource: "Generate-Response",
  total_inquiries_in_ticket: data.total_inquiries_in_ticket,
  inquiries,
};

const bodyPayload = `\`\`\`\\n\\n${escapeJSONStringForHTTP(payload)}\\n\\n`;

// ---- tags (sin cambios) ------------------------------------------------
let tags = [
  { id: "don:core:dvrv-us-1:devo/1is7v8y722:tag/2910" }
];

if (firstContact === false || firstContact === 'false') {
  tags.push({ id: "don:core:dvrv-us-1:devo/1is7v8y722:tag/2887" });
} else {
  tags.push({ id: "don:core:dvrv-us-1:devo/1is7v8y722:tag/2886" });
}

const tagString = tags.map(t => JSON.stringify(t)).join(",\n  ");

return {
  json: {
    ticketId: getFields.ticketId,
    body: bodyPayload,
    part: "CAPL-1",
    tag: tagString,
  }
};

